use std::process::ExitCode;

use wgpu::util::DeviceExt;

const SHADER: &str = r"
struct Params { width: u32, height: u32 }

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= params.width || id.y >= params.height) {
        return;
    }
    var count = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(id.x) + dx;
            let ny = i32(id.y) + dy;
            if (nx < 0 || ny < 0 || nx >= i32(params.width) || ny >= i32(params.height)) {
                continue;
            }
            count += src[u32(ny) * params.width + u32(nx)];
        }
    }
    let i = id.y * params.width + id.x;
    let alive = src[i] == 1u;
    dst[i] = select(u32(count == 3u), u32(count == 2u || count == 3u), alive);
}
";

fn parse(text: &str) -> Result<(usize, usize, u32, Vec<u32>), String> {
    let mut it = text.split_whitespace();
    let mut num = |what: &str| -> Result<usize, String> {
        it.next()
            .ok_or_else(|| format!("missing {what}"))?
            .parse::<usize>()
            .map_err(|e| format!("bad {what}: {e}"))
    };
    let w = num("width")?;
    let h = num("height")?;
    let gens = num("generations")?;
    let mut cells = Vec::with_capacity(w * h);
    // Cells may be space separated or packed; read digit by digit.
    for tok in it {
        for c in tok.chars() {
            match c {
                '0' => cells.push(0),
                '1' => cells.push(1),
                _ => return Err(format!("bad cell {c:?}")),
            }
        }
    }
    if w == 0 || h == 0 {
        return Err("empty grid".into());
    }
    if cells.len() < w * h {
        return Err("too few cells".into());
    }
    cells.truncate(w * h);
    Ok((w, h, u32::try_from(gens).map_err(|e| e.to_string())?, cells))
}

fn run(w: usize, h: usize, gens: u32, cells: &[u32]) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let size = (w * h * 4) as u64;
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(cells),
        usage: storage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&[w as u32, h as u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: wgpu::PipelineCompilationOptions::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
            ],
        })
    };
    let groups = [make_group(&buf_a, &buf_b), make_group(&buf_b, &buf_a)];

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    for g in 0..gens {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[(g % 2) as usize], &[]);
        pass.dispatch_workgroups(w.div_ceil(8) as u32, h.div_ceil(8) as u32, 1);
    }
    let result = if gens % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_life <input file>");
        return ExitCode::FAILURE;
    };
    let result = std::fs::read_to_string(&path)
        .map_err(|e| e.to_string())
        .and_then(|t| parse(&t))
        .and_then(|(w, h, g, cells)| run(w, h, g, &cells).map(|out| (w, out)));
    match result {
        Ok((w, out)) => {
            let mut s = String::new();
            for row in out.chunks(w) {
                let line: Vec<&str> = row.iter().map(|&c| if c == 1 { "1" } else { "0" }).collect();
                s.push_str(&line.join(" "));
                s.push('\n');
            }
            let alive = out.iter().filter(|&&c| c == 1).count();
            s.push_str(&format!("ALIVE {alive}\n"));
            print!("{s}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
